/// The CPU features `vg_ecdsa_brainpoolp512r1_rfc6979_sign_hash_shani` requires (`Artifact.features`).
pub(crate) const VG_ECDSA_BRAINPOOLP512R1_RFC6979_SIGN_HASH_SHANI_FEATURES: crate::cpu::Features = crate::cpu::Features::of(&["sha", "ssse3"]);

